+        this.path = path;
+        this.reload = reload;
+    }
+
+    @Override
+    public void onFileCreated(Path file) {
+        onFileChanged(file);
+    }
+
+    @Override
+    public void onFileDeleted(Path file) {
+        onFileChanged(file);
+    }
+
+    @Override
+    public void onFileChanged(Path file) {
+        if (file.equals(this.path)) {
+            reload.run();
+        }
+    }
+}

